#!/usr/bin/env python3
# Reconstructs a compact 384 px copper/black icon derived from the user's original NobleEthan emblem.
# Four luminance levels faithfully preserve the emblem outline/lettering while remaining lightweight.
import base64,zlib,struct,binascii,pathlib
W=H=384
PACKED=base64.b64decode("""""")
raw=zlib.decompress(PACKED)
assert len(raw)==W*H//4,("damaged supplied logo asset",len(raw))
colors=((10,10,10),(82,53,42),(163,105,78),(255,187,145))
scan=bytearray()
for y in range(H):
 scan.append(0)
 for x in range(W):
  b=raw[(y*W+x)//4]
  v=(b>>(6-2*(x%4)))&3
  scan.extend(colors[v])
def ch(t,d):
 return struct.pack(">I",len(d))+t+d+struct.pack(">I",binascii.crc32(t+d)&0xffffffff)
png=b"\x89PNG\r\n\x1a\n"+ch(b"IHDR",struct.pack(">IIBBBBB",W,H,8,2,0,0,0))+ch(b"IDAT",zlib.compress(scan,9))+ch(b"IEND",b"")
out=pathlib.Path("app/src/main/res/drawable-nodpi/nobleethan.png")
out.parent.mkdir(parents=True,exist_ok=True)
out.write_bytes(png)
print("NobleEthan branded icon and splash:",out,len(png),"bytes")
